import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv_transpose3d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch, int in_channels, int out_channels,
    int D_in, int H_in, int W_in,
    int D_out, int H_out, int W_out,
    int kD, int kH, int kW,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int groups,
    int in_channels_per_group, int out_channels_per_group)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    long total = (long)batch * out_channels * D_out * H_out * W_out;
    if (idx >= total) return;

    int ow = idx % W_out;
    int tmp = idx / W_out;
    int oh = tmp % H_out;
    tmp = tmp / H_out;
    int od = tmp % D_out;
    tmp = tmp / D_out;
    int oc = tmp % out_channels;
    int b = tmp / out_channels;

    int g = oc / out_channels_per_group;
    int oc_in_group = oc % out_channels_per_group;

    float sum = 0.0f;

    for (int ic_in_group = 0; ic_in_group < in_channels_per_group; ic_in_group++) {
        int ic = g * in_channels_per_group + ic_in_group;
        for (int kd = 0; kd < kD; kd++) {
            int id_nom = od + pad_d - kd;
            if (id_nom % stride_d != 0) continue;
            int id = id_nom / stride_d;
            if (id < 0 || id >= D_in) continue;
            for (int kh = 0; kh < kH; kh++) {
                int ih_nom = oh + pad_h - kh;
                if (ih_nom % stride_h != 0) continue;
                int ih = ih_nom / stride_h;
                if (ih < 0 || ih >= H_in) continue;
                for (int kw = 0; kw < kW; kw++) {
                    int iw_nom = ow + pad_w - kw;
                    if (iw_nom % stride_w != 0) continue;
                    int iw = iw_nom / stride_w;
                    if (iw < 0 || iw >= W_in) continue;

                    int input_idx = (((b * in_channels + ic) * D_in + id) * H_in + ih) * W_in + iw;
                    int weight_idx = (((ic * out_channels_per_group + oc_in_group) * kD + kd) * kH + kh) * kW + kw;
                    sum += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }

    if (bias != nullptr) {
        sum += bias[oc];
    }

    output[idx] = sum;
}

torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int out_pad_d, int out_pad_h, int out_pad_w,
    int groups)
{
    input = input.contiguous();
    weight = weight.contiguous();

    int batch = input.size(0);
    int in_channels = input.size(1);
    int D_in = input.size(2);
    int H_in = input.size(3);
    int W_in = input.size(4);

    int out_channels_per_group = weight.size(1);
    int out_channels = out_channels_per_group * groups;
    int kD = weight.size(2);
    int kH = weight.size(3);
    int kW = weight.size(4);

    int in_channels_per_group = in_channels / groups;

    int D_out = (D_in - 1) * stride_d - 2 * pad_d + kD + out_pad_d;
    int H_out = (H_in - 1) * stride_h - 2 * pad_h + kH + out_pad_h;
    int W_out = (W_in - 1) * stride_w - 2 * pad_w + kW + out_pad_w;

    auto output = torch::zeros({batch, out_channels, D_out, H_out, W_out}, input.options());

    long total = (long)batch * out_channels * D_out * H_out * W_out;
    int threads = 256;
    int blocks = (total + threads - 1) / threads;

    const float* bias_ptr = nullptr;
    if (bias.defined() && bias.numel() > 0) {
        bias = bias.contiguous();
        bias_ptr = bias.data_ptr<float>();
    }

    conv_transpose3d_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch, in_channels, out_channels,
        D_in, H_in, W_in,
        D_out, H_out, W_out,
        kD, kH, kW,
        stride_d, stride_h, stride_w,
        pad_d, pad_h, pad_w,
        groups,
        in_channels_per_group, out_channels_per_group
    );

    return output;
}
"""

conv_transpose3d_header = r"""
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int out_pad_d, int out_pad_h, int out_pad_w,
    int groups);
"""

conv_transpose3d_module = load_inline(
    name="conv_transpose3d_module",
    cpp_sources=conv_transpose3d_header,
    cuda_sources=conv_transpose3d_source,
    functions=["conv_transpose3d_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0),
                 output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()

        # Use nn.ConvTranspose3d to initialize weight/bias exactly like PyTorch does
        ref = nn.ConvTranspose3d(in_channels, out_channels, kernel_size,
                                  stride=stride, padding=padding,
                                  output_padding=output_padding, groups=groups, bias=bias)

        self.weight = nn.Parameter(ref.weight.data.clone())
        if bias:
            self.bias = nn.Parameter(ref.bias.data.clone())
        else:
            self.register_parameter('bias', None)

        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups

        self.conv_transpose3d_cuda = conv_transpose3d_module.conv_transpose3d_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        weight = self.weight.cuda().contiguous()
        bias_tensor = self.bias.cuda().contiguous() if self.bias is not None else torch.tensor([], device=x.device, dtype=x.dtype)

        out = self.conv_transpose3d_cuda(
            x, weight, bias_tensor,
            self.stride[0], self.stride[1], self.stride[2],
            self.padding[0], self.padding[1], self.padding[2],
            self.output_padding[0], self.output_padding[1], self.output_padding[2],
            self.groups
        )
        return out


